tool_input.new_string:
// Land paying customers in venue setup: an unprofiled location runs its
// first report on generic quick-service defaults. An abandoned checkout
// returns to Billing, where a pending account can resume it (/register is
// a public-only route, so a signed-in user was bounced to the dashboard).
success_url: `${CLIENT_URL}/venue-setup?first=1&onboarding=success`,
cancel_url: `${CLIENT_URL}/billing?checkout=cancelled`,

tool_input.old_string:
  select: { planStatus: true },
});

if (!user) {
  return res.status(401).json({ error: 'User not found.' });
}

const { planStatus } = user;

if (planStatus === 'active') {
  return next();
}

tool_input.new_string:
  select: { planStatus: true, onboardingPaid: true },
});

if (!user) {
  return res.status(401).json({ error: 'User not found.' });
}

const { planStatus } = user;

if (planStatus === 'active') {
  return next();
}

// 'pending' = signed up but the subscription isn't live yet. Tell the user
// which side of checkout they're on rather than a generic "inactive".
if (planStatus === 'pending') {
  if (!user.onboardingPaid) {
    return res.status(402).json({
      error: "Checkout wasn't completed, so your account isn't active yet. Resume checkout on the Billing page to start uploading.",
      code: 'CHECKOUT_INCOMPLETE',
    });
  }
  return res.status(402).json({
    error: "We've received your payment and are activating your account. Please try again in a minute, or contact support if this persists.",
    code: 'ACTIVATION_PENDING',
  });
}
